pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 public totalSupply;

    function setUp() public {
        c = new C();
        totalSupply = 0;
    }

    function testFuzz_property(uint256 numCalls, address[5] memory callers, uint8[5] memory seed) public {
        // Bound the number of calls to a reasonable range for fuzzing.
        uint256 n = bound(numCalls, 0, 10);
        // Track the number of successful airDrops observed.
        uint256 successCount = 0;

        // We need each caller to be a Bank contract that returns the correct supportsToken.
        // Deploy a Bank helper for each unique caller that the fuzzer provides.
        // The fuzzer supplies raw addresses; we need them to have code, so we deploy a helper
        // at a deterministic address derived from the fuzzed address.
        // However, we cannot deploy code at an arbitrary address without using vm.etch (disallowed).
        // Instead, we use a single Bank helper contract and have the test contract impersonate
        // each caller via prank. The supportsToken modifier calls Bank(msg.sender).supportsToken().
        // Since msg.sender will be a fuzzed EOA, that call will succeed but return nothing (or revert if no code).
        // A call to an EOA with no code does not revert; it returns success with empty data, which is bytes32(0).
        // This will fail the require(keccak256... == ...), so airDrop would always revert.
        // To satisfy the modifier, the caller must be a contract returning the right value.
        // The only way to have the caller be a contract is to deploy a helper contract and use its address.
        // But we cannot deploy at the fuzzer's arbitrary address.
        // The rule's difference: the mutant allows multiple airDrops per address because the hasNoBalance
        // modifier is defeated by the tautology. The original contract enforces one-time airdrop.
        // To trigger this, we need the same caller to call airDrop multiple times. With the correct supportsToken
        // check, the caller must be a Bank contract. We can deploy a Bank helper and use prank to act as it.
        // Since we want to fuzz over callers, we can deploy multiple Bank helpers and map them.
        // But the fuzzer supplies addresses; we cannot force the fuzzer to use our deployed addresses.
        // However, we can treat the fuzzed addresses as salt and deploy Bank contracts for each, then use their addresses.
        // Using CREATE2, we can deploy Bank at deterministic addresses based on the fuzzed callers.
        // This gives us contract addresses that we can use with vm.prank.
        // We'll deploy an array of Bank contracts and use them as callers.

        address[5] memory bankCallers;
        for (uint i = 0; i < 5; i++) {
            // Use the fuzzed address as salt to deploy a Bank helper.
            // Deploy via a helper factory.
            // We can use `new Bank{salt: bytes32(uint256(uint160(callers[i])))}(...)` but Bank has no constructor arguments.
            // So we can deploy a Bank contract directly with the salt.
            bankCallers[i] = address(new Bank{salt: bytes32(uint256(uint160(callers[i])))})());
        }

        // Track balances for each caller before and after calls to compute totalSupply changes.
        uint256[] memory initialBalances = new uint256[](5);
        for (uint i = 0; i < 5; i++) {
            initialBalances[i] = c.tokenBalance(bankCallers[i]);
        }

        for (uint256 j = 0; j < n; j++) {
            uint8 idx = seed[j % 5] % 5;
            address caller = bankCallers[idx];
            vm.prank(caller);
            try c.airDrop() {
                successCount++;
            } catch {
                // airDrop reverted, do nothing.
            }
        }

        // Collect final balances and compute totalSupply as sum of all tokenBalance entries.
        // Since the mapping is sparse, we can only observe balances for the addresses we called.
        // The total supply should be sum over all addresses that have non-zero balance.
        // But we only know the balances of our 5 callers. Other addresses could have been affected
        // via previous fuzz runs? No, setUp() creates a fresh C each test case.
        // So totalSupply is sum of balances of all addresses we interacted with.
        // The invariant: totalSupply == successCount * 20.
        uint256 finalTotal = 0;
        for (uint i = 0; i < 5; i++) {
            finalTotal += c.tokenBalance(bankCallers[i]);
        }

        assertTrue(finalTotal == successCount * 20);
    }
}

