pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address first, address second) public {
        vm.assume(first != second);
        vm.assume(first != address(0) && second != address(0));
        vm.assume(first.code.length == 0 && second.code.length == 0);

        // Deploy a Bank that supports the token so both addresses pass the supportsToken check
        Bank bank = new Bank();
        vm.prank(first);
        // We simulate the Bank returning the correct hash by using the same Bank contract.
        // The C contract calls Bank(msg.sender).supportsToken(), so we need msg.sender to be a Bank.
        // To make first able to call airDrop, we must have first code return the valid hash.
        // Fuzzed addresses are EOAs with no code, so we deploy an adversarial helper that acts as a compliant Bank
        // and set its address as the caller? No, the modifier uses msg.sender as the Bank address.
        // We need msg.sender to be a Bank. We cannot change the caller's code.
        // So we deploy a Bank at a predictable address? No.
        // We PRANK a call from the Bank itself? That works: Bank.supportsToken() returns the correct bytes32.
        // But then first is the Bank address, and we need two distinct callers. We can deploy two Bank instances.
        // Actually, the modifier supportsToken does: require(keccak256("Nu Token") == Bank(msg.sender).supportsToken());
        // So we can simply prank from any contract that has supportsToken returning the right bytes32.
        // The Bank contract exists in source. We can deploy Bank and prank from that deployed address.
        // That address will have the correct code.
        // So we use two fresh Bank deployments as our two callers.
        vm.prank(address(bank));
        try c.airDrop() {} catch {}

        bool firstLockedAfter = c._locked();

        // Now the invariant: after a successful airdrop, _locked must be false.
        // If first airdrop succeeded, _locked must be false.
        // We also try a second airdrop from a different bank to see if it reverts.
        Bank bank2 = new Bank();
        vm.prank(address(bank2));
        bool secondOk = true;
        try c.airDrop() { secondOk = true; } catch { secondOk = false; }

        // The reference C should have _locked false after first call, and second call succeeds.
        // The buggy M has _locked true after first call, so second call reverts.
        // The general rule: if first call succeeded, then second call must succeed as well.
        // We can assert: (first succeeded) => (second succeeded)
        // Since first call cannot revert (no prior balance, correct Bank), we assert secondOk == true.
        // But we cannot guarantee first always succeeds without assuming the Bank code is correct. It is.
        // So we can assert that the second call does not revert.
        assertTrue(secondOk);
    }
}

